/// <reference types="vitest/config" />
import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import { VitePWA } from "vite-plugin-pwa";

export default defineConfig({
  plugins: [
    react(),
    // M3: a service worker (generated by Workbox) keeps a copy of the app files, so the app opens
    // without a network; the manifest makes it installable ("Dodaj do ekranu głównego").
    VitePWA({
      registerType: "autoUpdate", // a new version replaces the old one on the next start, no prompt
      includeAssets: ["favicon.svg", "icons/apple-touch-icon.png"],
      manifest: {
        name: "Quadernote",
        short_name: "Quadernote",
        description: "Zeszyt do włoskiego: wpisuj na lekcji, AI uzupełnia po lekcji.",
        lang: "pl",
        start_url: "/",
        scope: "/",
        display: "standalone",
        background_color: "#f3f4f1",
        theme_color: "#c8321b",
        icons: [
          { src: "icons/icon-192.png", sizes: "192x192", type: "image/png" },
          { src: "icons/icon-512.png", sizes: "512x512", type: "image/png" },
          { src: "icons/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
        ],
      },
      workbox: {
        globPatterns: ["**/*.{js,css,html,svg,png,webmanifest}"],
        navigateFallback: "/index.html",
        navigateFallbackDenylist: [/^\/api\//], // the API is never answered from the cache
        runtimeCaching: [
          {
            // Fonts: from the network once, then from the cache (also offline).
            urlPattern: /^https:\/\/fonts\.(googleapis|gstatic)\.com\/.*/,
            handler: "CacheFirst",
            options: {
              cacheName: "fonts",
              expiration: { maxEntries: 30, maxAgeSeconds: 365 * 24 * 3600 },
              cacheableResponse: { statuses: [0, 200] },
            },
          },
        ],
      },
    }),
  ],
  // `npm run dev` talks to the local API (uv run uvicorn app.main:app) on port 8000.
  server: { proxy: { "/api": "http://127.0.0.1:8000" } },
  // `vite preview` (gate M1) must stay server-less, so it does not inherit the proxy.
  preview: { proxy: {} },
  test: { environment: "node", include: ["src/**/*.test.ts"] },
});
